import sys
sys.setrecursionlimit(10 ** 6)
book = dict()
a = []
n = kk = rs0 = 0

def outc(k, j, v, rs):
	if (k, j, tuple(v)) in book.keys() and rs == rs0:
		return book[k, j, tuple(v)]
	elif rs != 0 and j != n:
		res = False
		if not v[j]:
			if a[j] <= rs:
				w = v.copy()
				w[j] = True
				res = res or outc(k, j + 1, w, rs - a[j])
		res = res or outc(k, j + 1, v, rs)
		book[k, j, tuple(v)] = res
		return res
	elif rs != 0 and j == n:
		return False
	elif rs == 0 and k != kk - 1:
		return outc(k + 1, 0, v, rs0)
	else:
		return True
T = int(input())
for _ in range(T):
	(N, K) = map(int, input().split())
	A = list(map(int, input().split()))
	a = A
	(n, kk) = (N, K)
	mysum = sum(A)
	if N < K or mysum % K != 0:
		print('no')
	else:
		rs0 = mysum // K
		if outc(0, 0, [False] * N, rs0):
			print('yes')
		else:
			print('no')
	book.clear()
